package com.campus.personnel.application;
import java.time.Clock; import java.util.*; import com.campus.organization.application.OrganizationUnitManagementService; import com.campus.organization.domain.OrganizationUnitStatus; import com.campus.personnel.domain.*; import org.springframework.dao.DataIntegrityViolationException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class FacultyStaffManagementService { private final FacultyStaffRepository members; private final OrganizationUnitManagementService organizations; private final Clock clock; public FacultyStaffManagementService(FacultyStaffRepository m,OrganizationUnitManagementService o,Clock c){members=m;organizations=o;clock=c;} @Transactional public FacultyStaffMember create(String n,String name,String email,PersonnelType type,UUID unit,PersonnelStatus status){unit(unit);FacultyStaffMember m;try{m=FacultyStaffMember.create(UUID.randomUUID(),n,name,email,type,unit,status==null?PersonnelStatus.ACTIVE:status,clock.instant());}catch(FacultyStaffMember.InvalidFacultyStaffMemberException e){throw new RequestValidationException();}if(members.existsByPersonnelNumber(m.personnelNumber()))throw new PersonnelNumberAlreadyExistsException();try{return members.save(m);}catch(DataIntegrityViolationException e){throw new PersonnelNumberAlreadyExistsException();}} @Transactional(readOnly=true) public FacultyStaffMember get(UUID id){return members.findById(id).orElseThrow(FacultyStaffNotFoundException::new);} @Transactional(readOnly=true) public List<FacultyStaffMember> list(){return members.findAll();} @Transactional public FacultyStaffMember update(UUID id,String n,String name,String email,PersonnelType type,UUID unit,PersonnelStatus status,long version){FacultyStaffMember old=get(id);unit(unit);FacultyStaffMember next;try{next=new FacultyStaffMember(id,n,name,email,type,unit,status,old.rowVersion(),old.createdAt(),clock.instant());}catch(FacultyStaffMember.InvalidFacultyStaffMemberException e){throw new RequestValidationException();}try{return members.saveMutation(next,version);}catch(NoSuchElementException e){throw new FacultyStaffNotFoundException();}catch(DataIntegrityViolationException e){throw new PersonnelNumberAlreadyExistsException();}} private void unit(UUID id){try{if(organizations.get(id).status()!=OrganizationUnitStatus.ACTIVE)throw new OrganizationUnitUnavailableException();}catch(OrganizationUnitManagementService.OrganizationUnitNotFoundException e){throw new OrganizationUnitUnavailableException();}} public static final class FacultyStaffNotFoundException extends RuntimeException{} public static final class PersonnelNumberAlreadyExistsException extends RuntimeException{} public static final class ConcurrentFacultyStaffModificationException extends RuntimeException{} public static final class OrganizationUnitUnavailableException extends RuntimeException{} public static final class RequestValidationException extends RuntimeException{} }
